const lastMsg = $('Check Last Message').first().json;
const metaSub = $('Check Meta Status').first().json;
const phoneStatus = $('Check Phone Status').first().json;

const now = new Date();
const issues = [];
let lastMessageTime = null;
let minutesSinceLastMessage = null;

// Fix: lastMsg is a flat object from Supabase REST API, not an array
if (lastMsg && lastMsg.timestamp) {
  lastMessageTime = new Date(lastMsg.timestamp);
  minutesSinceLastMessage = Math.round((now - lastMessageTime) / 60000);
  // Only alert if no messages in 48 hours — appropriate for low-traffic WhatsApp bot
  if (minutesSinceLastMessage > 2880) {
    issues.push('NO_MESSAGES: No WhatsApp messages received in ' + minutesSinceLastMessage + ' minutes (last: ' + lastMessageTime.toISOString() + ')');
  }
} else if (!lastMsg || Object.keys(lastMsg).length === 0) {
  issues.push('NO_HISTORY: No conversation history found in Supabase - webhook may never have received a message');
}

const subData = metaSub?.data || [];
if (subData.length === 0) {
  issues.push('NOT_SUBSCRIBED: Meta app is NOT subscribed to WABA - webhooks will not be delivered');
}

if (phoneStatus?.status !== 'CONNECTED') {
  issues.push('PHONE_DOWN: Phone number status is ' + (phoneStatus?.status || 'UNKNOWN') + ' (expected: CONNECTED)');
}

if (!phoneStatus?.webhook_configuration?.application) {
  issues.push('NO_WEBHOOK_URL: No webhook callback URL configured on phone number');
}

// --- Campaign scheduler heartbeat ---
// /api/campaigns/process stamps system_heartbeats every run (every 15 min).
// A stale or missing row means the scheduler silently died.
let heartbeatRow = null;
try {
  const hb = $('Check Scheduler Heartbeat').first().json;
  heartbeatRow = Array.isArray(hb) ? hb[0] : hb;
} catch (e) {}
let schedulerAgeMinutes = null;
if (!heartbeatRow || !heartbeatRow.last_run_at) {
  issues.push('SCHEDULER_NO_HEARTBEAT: No campaign_process heartbeat found - scheduler may never have run or the check failed');
} else {
  schedulerAgeMinutes = Math.round((now - new Date(heartbeatRow.last_run_at)) / 60000);
  if (schedulerAgeMinutes > 45) {
    issues.push('SCHEDULER_STALE: Campaign process last ran ' + schedulerAgeMinutes + ' minutes ago (expected every 15) - n8n scheduler workflow may be down');
  }
}

const isHealthy = issues.length === 0;

// Deduplication: normalize the alert key by stripping dynamic numbers
// This prevents the same issue from re-triggering every 30 min just because the minute count changed
const staticData = $getWorkflowStaticData('global');
const issuesKey = issues.map(function(i) { return i.split(':')[0]; }).sort().join('|');
const lastAlertKey = staticData.lastAlertKey || '';
const lastAlertTime = staticData.lastAlertTime ? new Date(staticData.lastAlertTime) : null;
const COOLDOWN_MINUTES = 1440; // Don't re-send the same alert type within 24 hours

let shouldSendAlert = !isHealthy;
if (shouldSendAlert && issuesKey === lastAlertKey && lastAlertTime) {
  const minutesSinceLastAlert = Math.round((now - lastAlertTime) / 60000);
  if (minutesSinceLastAlert < COOLDOWN_MINUTES) {
    shouldSendAlert = false;
  }
}

// Update static data when sending an alert
if (shouldSendAlert) {
  staticData.lastAlertKey = issuesKey;
  staticData.lastAlertTime = now.toISOString();
}

// If healthy, reset the alert key so a new issue will trigger immediately
if (isHealthy) {
  staticData.lastAlertKey = '';
}

return {
  json: {
    isHealthy,
    shouldSendAlert,
    issues: issues,
    issuesCount: issues.length,
    lastMessageTime: lastMessageTime ? lastMessageTime.toISOString() : null,
    minutesSinceLastMessage,
    metaSubscribed: subData.length > 0,
    phoneStatus: phoneStatus?.status || 'UNKNOWN',
    codeVerificationStatus: phoneStatus?.code_verification_status || 'UNKNOWN',
    qualityRating: phoneStatus?.quality_rating || 'UNKNOWN',
    webhookUrl: phoneStatus?.webhook_configuration?.application || 'NOT SET',
    schedulerLastRunAt: heartbeatRow?.last_run_at || null,
    schedulerAgeMinutes,
    timestamp: now.toISOString()
  }
};

const health = $json;
const issues = health.issues || [];
const issuesList = issues.map(function(i) { return '<li style="padding: 5px 0; color: #dc3545;">' + i + '</li>'; }).join('');

var htmlContent = '<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">';
htmlContent += '<div style="background: #dc3545; padding: 20px; border-radius: 10px 10px 0 0; text-align: center;">';
htmlContent += '<h1 style="color: white; margin: 0;">WhatsApp Webhook Health Alert</h1>';
htmlContent += '<p style="color: white; margin: 5px 0 0 0;">Meta webhook delivery may be interrupted</p>';
htmlContent += '</div>';
htmlContent += '<div style="padding: 20px; border: 1px solid #ddd; border-top: none; border-radius: 0 0 10px 10px;">';
htmlContent += '<h2 style="color: #333; border-bottom: 2px solid #dc3545; padding-bottom: 10px;">Issues Detected</h2>';
htmlContent += '<ul style="padding-left: 20px;">' + issuesList + '</ul>';
htmlContent += '<h2 style="color: #333; border-bottom: 2px solid #dc3545; padding-bottom: 10px; margin-top: 20px;">System Status</h2>';
htmlContent += '<table style="width: 100%; border-collapse: collapse;">';
htmlContent += '<tr><td style="padding: 8px; font-weight: bold;">Last Message Received:</td><td style="padding: 8px;">' + (health.lastMessageTime || 'Never') + '</td></tr>';
htmlContent += '<tr><td style="padding: 8px; font-weight: bold;">Minutes Since Last:</td><td style="padding: 8px;">' + (health.minutesSinceLastMessage || 'N/A') + '</td></tr>';
htmlContent += '<tr><td style="padding: 8px; font-weight: bold;">Meta App Subscribed:</td><td style="padding: 8px;">' + (health.metaSubscribed ? 'Yes' : 'NO') + '</td></tr>';
htmlContent += '<tr><td style="padding: 8px; font-weight: bold;">Phone Status:</td><td style="padding: 8px;">' + health.phoneStatus + '</td></tr>';
htmlContent += '<tr><td style="padding: 8px; font-weight: bold;">Code Verification:</td><td style="padding: 8px;">' + health.codeVerificationStatus + '</td></tr>';
htmlContent += '<tr><td style="padding: 8px; font-weight: bold;">Quality Rating:</td><td style="padding: 8px;">' + health.qualityRating + '</td></tr>';
htmlContent += '<tr><td style="padding: 8px; font-weight: bold;">Webhook URL:</td><td style="padding: 8px;">' + health.webhookUrl + '</td></tr>';
htmlContent += '<tr><td style="padding: 8px; font-weight: bold;">Check Time:</td><td style="padding: 8px;">' + health.timestamp + '</td></tr>';
htmlContent += '</table>';
htmlContent += '<h2 style="color: #333; border-bottom: 2px solid #dc3545; padding-bottom: 10px; margin-top: 20px;">Troubleshooting Steps</h2>';
htmlContent += '<ul style="padding-left: 20px;">';
htmlContent += '<li style="padding: 5px 0;">Check Meta Developer Dashboard: <a href="https://developers.facebook.com/apps/1042510698362546">Open App</a></li>';
htmlContent += '<li style="padding: 5px 0;">Verify app is in LIVE mode (not Development)</li>';
htmlContent += '<li style="padding: 5px 0;">Check WhatsApp > Configuration > Callback URL and subscribed fields</li>';
htmlContent += '<li style="padding: 5px 0;">Verify n8n is running and webhook endpoint responds</li>';
htmlContent += '<li style="padding: 5px 0;">Check Caddy logs for Meta POST requests: docker logs n8n-caddy-1 --since=1h | grep whatsapp</li>';
htmlContent += '<li style="padding: 5px 0;">Re-subscribe app: POST https://graph.facebook.com/v21.0/1613835747059073/subscribed_apps</li>';
htmlContent += '</ul>';
htmlContent += '<hr style="margin-top: 20px; border: none; border-top: 1px solid #ddd;">';
htmlContent += '<p style="color: #999; font-size: 12px; text-align: center;">This alert was generated by the WhatsApp Webhook Health Monitor (runs every 30 minutes)</p>';
htmlContent += '</div></div>';

return { json: {
  sender: { name: 'Horizon Africa AI', email: 'keshlan@horizonafrica.co.za' },
  to: [{ email: 'sifosman@gmail.com', name: 'Mohamed' }],
  subject: 'WhatsApp Webhook Health Alert - ' + issues.length + ' issue(s) detected',
  htmlContent: htmlContent
} };

